import re
def load(p):
    d={}
    for line in open(p):
        m=re.match(r'^- (F-\d+) ',line)
        if m: d[m.group(1)]=line.rstrip('\n')
    return d
def loadq(p):
    d={}
    for line in open(p):
        m=re.match(r'^- (F-\d+) ',line)
        if m: d.setdefault(m.group(1),line.rstrip('\n'))
    return d
r1=load('rec-pilot-1/explorations/coordinator/FACTS.md')
r2=load('rec-pilot-2/explorations/coordinator/FACTS.md')
m=load('fortress/explorations/coordinator/FACTS.md')
base='fortress/explorations/coordinator/postmortem-2026-11-24-record-regrowth/evidence/pilot-hand/test/'
qq=loadq(base+'questions-q.md'); pp=loadq(base+'questions-p.md')
for k in qq:
    src = 'r1' if r1.get(k)!=m.get(k) else ('r2' if r2.get(k)!=m.get(k) else 'main')
    cand = {'r1':r1.get(k),'r2':r2.get(k),'main':m.get(k)}[src]
    print(k, 'q from', src, 'match', qq[k]==cand, '| p matches main', pp.get(k)==m.get(k))
EOF

